import type { AdaptiveQualityTier } from '../render/adaptive-quality';

export type FieldDetailStage = 'hero' | 'near' | 'mid' | 'far' | 'culled';

export interface FieldViewState {
  cameraX: number;
  cameraY: number;
  cameraZ: number;
  forwardX: number;
  forwardY: number;
  forwardZ: number;
  rightX: number;
  rightY: number;
  rightZ: number;
  upX: number;
  upY: number;
  upZ: number;
  tanHalfFov: number;
  aspect: number;
}

export interface FieldOptimizationTarget {
  x: number;
  y: number;
  z: number;
  radius: number;
}

export interface FieldOptimizationDecision {
  stage: FieldDetailStage;
  visible: boolean;
  petalFraction: number;
  leafFraction: number;
  animationDivisor: number;
}

/** Conservative cross-device height for Three.js' per-instance morph texture. */
export const MAX_MORPH_TEXTURE_INSTANCES = 4096;

export const resolveMorphBatchPlantLimit = (maximumPetalsPerPlant: number): number =>
  Math.max(1, Math.floor(MAX_MORPH_TEXTURE_INSTANCES / Math.max(1, Math.round(maximumPetalsPerPlant))));

const BASE_PROFILE: Record<Exclude<FieldDetailStage, 'culled'>, Omit<FieldOptimizationDecision, 'stage' | 'visible'>> = {
  hero: { petalFraction: 1, leafFraction: 1, animationDivisor: 1 },
  near: { petalFraction: 0.84, leafFraction: 0.8, animationDivisor: 1 },
  mid: { petalFraction: 0.58, leafFraction: 0.52, animationDivisor: 2 },
  far: { petalFraction: 0.34, leafFraction: 0.26, animationDivisor: 4 },
};

const CULLED: FieldOptimizationDecision = {
  stage: 'culled',
  visible: false,
  petalFraction: 0,
  leafFraction: 0,
  animationDivisor: 8,
};

const dot = (x: number, y: number, z: number, ax: number, ay: number, az: number): number =>
  x * ax + y * ay + z * az;

const qualityAdjusted = (
  stage: Exclude<FieldDetailStage, 'culled'>,
  tier: AdaptiveQualityTier,
): FieldOptimizationDecision => {
  const base = BASE_PROFILE[stage];
  const detailScale = tier === 'reduced' ? 0.72 : tier === 'cinematic' ? 1.14 : 1;
  const cadenceScale = tier === 'reduced' ? 2 : tier === 'cinematic' ? 0.75 : 1;
  return {
    stage,
    visible: true,
    petalFraction: Math.min(1, base.petalFraction * detailScale),
    leafFraction: Math.min(1, base.leafFraction * detailScale),
    animationDivisor: Math.max(1, Math.round(base.animationDivisor * cadenceScale)),
  };
};

/**
 * Camera-aware five-stage LOD. The same adaptive tier that controls the
 * renderer's post effects also shifts geometry density and animation cadence.
 */
export const resolveFieldOptimizationDecision = (
  target: FieldOptimizationTarget,
  view: FieldViewState,
  fieldRadius: number,
  tier: AdaptiveQualityTier,
): FieldOptimizationDecision => {
  const dx = target.x - view.cameraX;
  const dy = target.y - view.cameraY;
  const dz = target.z - view.cameraZ;
  const depth = dot(dx, dy, dz, view.forwardX, view.forwardY, view.forwardZ);
  const horizontal = dot(dx, dy, dz, view.rightX, view.rightY, view.rightZ);
  const vertical = dot(dx, dy, dz, view.upX, view.upY, view.upZ);
  const safeDepth = Math.max(0, depth);
  const horizontalLimit = safeDepth * view.tanHalfFov * Math.max(0.25, view.aspect) + target.radius;
  const verticalLimit = safeDepth * view.tanHalfFov + target.radius;
  if (
    depth + target.radius <= 0
    || Math.abs(horizontal) > horizontalLimit
    || Math.abs(vertical) > verticalLimit
  ) return CULLED;

  const distance = Math.hypot(dx, dy, dz);
  const safeRadius = Math.max(2, fieldRadius);
  const distanceScale = tier === 'reduced' ? 0.84 : tier === 'cinematic' ? 1.12 : 1;
  const heroDistance = Math.max(3.2, safeRadius * 0.48) * distanceScale;
  const nearDistance = Math.max(6, safeRadius * 1.08) * distanceScale;
  const midDistance = Math.max(10, safeRadius * 1.75) * distanceScale;
  const farDistance = Math.max(18, safeRadius * 3.15) * distanceScale;

  if (distance <= heroDistance) return qualityAdjusted('hero', tier);
  if (distance <= nearDistance) return qualityAdjusted('near', tier);
  if (distance <= midDistance) return qualityAdjusted('mid', tier);
  if (distance <= farDistance) return qualityAdjusted('far', tier);
  return CULLED;
};

/** Keeps entire repeated-organ groups while distributing retained groups evenly. */
export const retainDetailGroup = (
  groupIndex: number,
  groupCount: number,
  fraction: number,
  minimumGroups = 1,
  seed = 0,
): boolean => {
  const safeCount = Math.max(1, Math.round(groupCount));
  const keepCount = Math.min(safeCount, Math.max(minimumGroups, Math.round(safeCount * fraction)));
  if (keepCount >= safeCount) return true;
  if (keepCount <= 0) return false;
  const offset = ((Math.imul(seed + 1, 2654435761) >>> 0) % safeCount) / safeCount;
  const before = Math.floor(((groupIndex / safeCount + offset) % 1) * keepCount);
  const after = Math.floor((((groupIndex + 1) / safeCount + offset) % 1) * keepCount);
  return after !== before || groupIndex === safeCount - 1;
};
